const envelope = $json || {};
const body = envelope.body || envelope;
const content = body.content || body.message || body.data?.content || {};
const contact = body.contact || body.sender || body.data?.contact || {};

let phone = String(
  contact.number ||
  contact.phone ||
  contact.id?.user ||
  body.phone ||
  body.sessionId ||
  ''
).replace(/\D/g, '');
if (!phone) return [{ json: { ignore: true } }];
if (!phone.startsWith('55')) phone = '55' + phone;

const chatInput = String(
  content.text || content.body || content.caption || body.message?.text || body.message || ''
).trim();

const doc = content.document || content.documentMessage || body.document || null;
const mediaBase64 =
  content.media || content.base64 || doc?.base64 || doc?.data || body.mediaBase64 || null;

const mimetype = String(
  content.mimetype || content.mimeType || doc?.mimetype || doc?.mime_type || body.mimetype || ''
).toLowerCase();

const fileName =
  content.fileName || content.filename || doc?.fileName || doc?.file_name || body.fileName || null;

if (!chatInput && !mediaBase64 && !mimetype && !fileName) {
  return [{ json: { ignore: true } }];
}

return [{
  json: {
    ignore: false,
    phone,
    sessionId: phone,
    chatInput,
    mediaBase64: mediaBase64 || null,
    mimetype: mimetype || '',
    fileName: fileName || null,
    rawPayload: body
  }
}];

const input = $json;
const staticData = getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};

const phone = String(input.phone || '').replace(/\D/g, '');
const key = phone || String(input.sessionId || 'default');
const now = Date.now();

const defaultState = () => ({
  stage: 'idle',
  pendingResume: null,
  lastDraftResume: null,
  lastDraftAt: null,
  lastSavedResume: null,
  lastSavedResumeAt: null,
  updatedAt: now,
});

const state = staticData.sessions[key] || defaultState();
state.updatedAt = now;

const text = String(input.chatInput || '').trim();
const ntext = text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const hasFile = !!input.mediaBase64 || !!input.fileName || (input.mimetype || '').includes('pdf');
const isAffirmative = /\b(sim|ok|beleza|blz|confirmo|pode cadastrar|pode salvar|manda ver|topo|combinado|fechou)\b/i.test(ntext);
const isCorrection = /\b(mas|corrig|ajust|alter|muda|troca|errad|meu email|meu telefone|cidade|cargo)\b/i.test(ntext) || /@\S+\.\S+/.test(text);

async function callOpenAI(messages, maxTokens = 900) {
  const apiKey = $env.OPENAI_API_KEY;
  if (!apiKey) throw new Error('OPENAI_API_KEY ausente no ambiente do n8n');
  const model = $env.OPENAI_MODEL || 'gpt-4o-mini';
  const resp = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ model, messages, temperature: 0.2, max_tokens: maxTokens }),
  });
  const data = await resp.json();
  if (!resp.ok) throw new Error(data?.error?.message || `OpenAI HTTP ${resp.status}`);
  return String(data?.choices?.[0]?.message?.content || '').trim();
}

function parseJsonFromText(raw) {
  const s = String(raw || '').replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  const m = s.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try { return JSON.parse(m[0]); } catch { return null; }
}

async function saveResumeToSupabase(resume) {
  const url = $env.SUPABASE_URL;
  const key = $env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) throw new Error('SUPABASE_URL ou SUPABASE_SERVICE_ROLE_KEY ausente no ambiente do n8n');

  const payload = {
    candidate_name: resume.fullName || null,
    candidate_email: resume.email || null,
    candidate_phone: phone,
    city: resume.city || null,
    position_of_interest: resume.jobInterest || null,
    file_name: resume.fileName || 'curriculo',
    file_path: resume.filePath || `webhook/evolux/${phone}/${encodeURIComponent(resume.fileName || 'curriculo')}`,
    file_size: Number.isFinite(Number(resume.fileSize)) ? Number(resume.fileSize) : 0,
    file_type: resume.mimetype || 'application/octet-stream',
    file_url: resume.fileUrl || `https://boteevoluxnovo.vercel.app/files/${encodeURIComponent(resume.fileName || 'curriculo')}`,
  };

  const r = await fetch(`${url}/rest/v1/resumes`, {
    method: 'POST',
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      'Content-Type': 'application/json',
      Prefer: 'return=representation',
    },
    body: JSON.stringify(payload),
  });

  const data = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(data?.message || data?.error || `Supabase HTTP ${r.status}`);
  return Array.isArray(data) ? data[0] : data;
}

let message = '';
let debug = null;

try {
  if (state.stage === 'await_confirm' && state.pendingResume) {
    if (isCorrection) {
      const updatedRaw = await callOpenAI([
        { role: 'system', content: 'Atualize os dados do currículo com base na mensagem do usuário. Retorne APENAS JSON com fullName,email,phone,city,jobInterest.' },
        { role: 'user', content: `Dados atuais: ${JSON.stringify(state.pendingResume)}\nMensagem: ${text}` },
      ], 500);
      const upd = parseJsonFromText(updatedRaw);
      if (upd) {
        state.pendingResume = { ...state.pendingResume, ...upd };
        state.lastDraftResume = state.pendingResume;
        state.lastDraftAt = new Date().toISOString();
        message = `Atualizei os dados:\nNome: ${state.pendingResume.fullName || '—'}\nEmail: ${state.pendingResume.email || '—'}\nTelefone: ${state.pendingResume.phone || phone || '—'}\nCidade: ${state.pendingResume.city || '—'}\nCargo: ${state.pendingResume.jobInterest || '—'}\n\nSe estiver certo, confirme com SIM/OK.`;
      } else {
        message = 'Não consegui entender a correção. Pode enviar no formato: "meu email é ..."';
      }
    } else if (isAffirmative) {
      const saved = await saveResumeToSupabase(state.pendingResume);
      state.lastSavedResume = saved || state.pendingResume;
      state.lastSavedResumeAt = new Date().toISOString();
      state.stage = 'idle';
      state.pendingResume = null;
      state.lastDraftResume = null;
      state.lastDraftAt = null;
      message = 'Perfeito! Candidatura registrada com sucesso. Obrigado.';
    } else {
      message = 'Se estiver tudo certo, responda com SIM/OK. Se precisar ajustar, escreva a correção (ex.: meu email é ...).';
    }
  } else if (hasFile) {
    const extractRaw = await callOpenAI([
      { role: 'system', content: 'Extraia dados de currículo e retorne APENAS JSON: {"fullName":null,"email":null,"phone":null,"city":null,"jobInterest":null}. Se não conseguir, use null.' },
      { role: 'user', content: `Mensagem: ${text || '(sem texto)'}\nArquivo: ${input.fileName || 'curriculo'}\nMimetype: ${input.mimetype || 'desconhecido'}\nBase64(início): ${String(input.mediaBase64 || '').slice(0, 7000)}` },
    ], 700);

    const extracted = parseJsonFromText(extractRaw);
    if (!extracted) {
      message = 'Recebi o arquivo, mas não consegui extrair os dados. Pode reenviar em PDF com texto selecionável?';
      state.stage = 'idle';
    } else {
      state.pendingResume = {
        ...extracted,
        fileName: input.fileName || 'curriculo',
        mimetype: input.mimetype || '',
        fileSize: 0,
      };
      state.lastDraftResume = state.pendingResume;
      state.lastDraftAt = new Date().toISOString();
      state.stage = 'await_confirm';

      message = `Encontrei estes dados:\nNome: ${state.pendingResume.fullName || '—'}\nEmail: ${state.pendingResume.email || '—'}\nTelefone: ${state.pendingResume.phone || phone || '—'}\nCidade: ${state.pendingResume.city || '—'}\nCargo: ${state.pendingResume.jobInterest || '—'}\n\nSe estiver certo, responda SIM/OK. Se quiser corrigir, escreva a correção.`;
    }
  } else if (isAffirmative && state.lastDraftResume) {
    const saved = await saveResumeToSupabase(state.lastDraftResume);
    state.lastSavedResume = saved || state.lastDraftResume;
    state.lastSavedResumeAt = new Date().toISOString();
    state.stage = 'idle';
    state.pendingResume = null;
    state.lastDraftResume = null;
    state.lastDraftAt = null;
    message = 'Confirmação recebida. Recuperei o rascunho interrompido e registrei a candidatura com sucesso.';
  } else {
    message = 'Perfeito! Para se candidatar, envie seu currículo em PDF, imagem ou DOCX para eu extrair os dados e confirmar com você.';
  }
} catch (e) {
  debug = String(e?.message || e);
  message = 'Houve uma falha temporária no processamento. Mantive seu estado em cache. Pode tentar novamente com a última mensagem.';
}

staticData.sessions[key] = state;

return [{
  json: {
    ok: true,
    phone,
    sessionId: key,
    message,
    ...(debug ? { error_debug: debug } : {}),
    mychatPayload: {
      number: phone,
      body: message,
      externalKey: `lead_${phone}`,
      isClosed: false,
    }
  }
}];

const item = $input.first().json || {};
const p = item.mychatPayload || {};
const number = String(p.number || item.phone || '').replace(/\D/g, '');
const msg = String(p.body || item.message || '').replace(/[\r\n]+/g, ' ').trim();
if (!number || !msg) throw new Error('Fluxo não retornou dados para MyChat');

return [{
  json: {
    number,
    body: msg,
    externalKey: p.externalKey || `lead_${number}`,
    isClosed: p.isClosed === true
  }
}];
